const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const all = await fs.readdir(S).catch(()=>[]);
// 最近 30 分钟内新建/修改的文件
const now = Date.now();
const recent = [];
for (const f of all) {
  try {
    const st = await fs.stat(S+"\\"+f);
    const ageMin = (now - st.mtimeMs)/60000;
    if (ageMin < 45) recent.push({ f, kb: Math.round(st.size/1024), ageMin: Math.round(ageMin) });
  } catch {}
}
recent.sort((a,b)=>a.ageMin-b.ageMin);
const jobs = await tools.job_list({});
const running = jobs.filter(j=>j.status==="running");
return { recentFiles: recent.slice(0,20), runningJobs: running.map(j=>String(j.id)+"|"+String(j.label).slice(0,60)) };
